function freshLife(){return {homes:{room:true},home:'room',decor:{},layouts:{},cars:{},car:'',view:'home',room:0,filter:'all'};}
function syncLife(s){const l=s.life||(s.life=freshLife());for(const h of HOMES)if(h.legacy&&s.items[h.legacy])l.homes[h.id]=true;for(const c of CARS)if(c.legacy&&s.items[c.legacy])l.cars[c.id]=true;return l;}
function normalizeLife(raw,s){const d=freshLife(),r=raw||{};for(const h of HOMES)if(r.homes?.[h.id]===true)d.homes[h.id]=true;for(const c of CARS)if(r.cars?.[c.id]===true)d.cars[c.id]=true;for(const i of DECOR)if(r.decor?.[i.id]===true)d.decor[i.id]=true;s.life=d;syncLife(s);d.home=HOMES.some(h=>h.id===r.home&&d.homes[h.id])?r.home:s.items.house?'house':s.items.apartment?'apartment':'room';d.car=CARS.some(c=>c.id===r.car&&d.cars[c.id])?r.car:s.items.car?'car':s.items.bike?'bike':'';d.view=['home','properties','decorate','garage','activities'].includes(r.view)?r.view:'home';d.room=Math.floor(num(r.room,5));d.filter=['all','seating','storage','lighting','accent'].includes(r.filter)?r.filter:'all';for(const h of HOMES){if(!d.homes[h.id])continue;const placed=new Set();d.layouts[h.id]={};for(let room=0;room<h.rooms;room++){const entries=r.layouts?.[h.id]?.[room]||{};d.layouts[h.id][room]={};for(const slot of ['seating','storage','lighting','accent']){const i=DECOR.find(i=>i.id===entries[slot]&&i.slot===slot&&d.decor[i.id]);if(i&&!placed.has(i.id)){d.layouts[h.id][room][slot]=i.id;placed.add(i.id);}}}}return d;}
function activeHome(s=S){const l=syncLife(s);return HOMES.find(h=>h.id===l.home)||HOMES[0];}
function lifeComfort(s=S){const l=syncLife(s),h=activeHome(s);let decor=0;for(const r of Object.values(l.layouts[h.id]||{}))for(const id of Object.values(r))decor+=DECOR.find(i=>i.id===id)?.comfort||0;const legacy=(s.items.apartment?3:0)+(s.items.house?4:0);return Math.max(0,h.comfort-legacy)+Math.min(30,decor);}
function vehicleBoost(s=S){const l=syncLife(s),c=CARS.find(c=>c.id===l.car);return Math.max(0,(c?.bonus||0)-(s.items.bike?.06:0)-(s.items.car?.1:0));}
function lifeWorth(s=S){const l=syncLife(s);return HOMES.reduce((n,h)=>n+(l.homes[h.id]&&!h.legacy?h.cost:0),0)+CARS.reduce((n,c)=>n+(l.cars[c.id]&&!c.legacy?c.cost:0),0)+DECOR.reduce((n,i)=>n+(l.decor[i.id]?i.cost:0),0);}
function buyLife(kind,id){const catalog=kind==='home'?HOMES:kind==='car'?CARS:kind==='decor'?DECOR:[];const item=catalog.find(i=>i.id===id),l=syncLife(S),owned=kind==='home'?l.homes:kind==='car'?l.cars:l.decor;if(!item||owned[id]||!spend(item.cost))return false;owned[id]=true;if(item.legacy)S.items[item.legacy]=true;if(kind==='home'){l.home=id;l.room=0;}if(kind==='car')l.car=id;note(item.name+' is yours.');return true;}
function chooseLife(kind,id){if(paused)return false;const l=syncLife(S);if(kind==='home'&&HOMES.some(h=>h.id===id)&&l.homes[id]){l.home=id;l.room=0;return true;}if(kind==='car'&&CARS.some(c=>c.id===id)&&l.cars[id]){l.car=id;return true;}return false;}
function placeDecor(id){if(paused)return false;const l=syncLife(S),h=activeHome(),i=DECOR.find(i=>i.id===id);if(!i||!l.decor[id]||l.room>=h.rooms)return false;const layout=l.layouts[h.id]||(l.layouts[h.id]={});for(const room of Object.values(layout))for(const slot of Object.keys(room))if(room[slot]===id)delete room[slot];const room=layout[l.room]||(layout[l.room]={});room[i.slot]=id;return true;}

function lifeArt(type,item){return '<img class="life-art" src="assets/life/'+type+'-'+item.id+'.webp?v=4" alt="" loading="lazy" decoding="async">';}
function roomPreview(){const l=syncLife(S),h=activeHome();l.room=Math.min(l.room,h.rooms-1);const room=l.layouts[h.id]?.[l.room]||{};return '<div class="room-preview"><div class="room-window"><i></i></div><span class="room-name">'+ROOMS[l.room]+'</span><div class="room-pieces">'+['storage','lighting','seating','accent'].map(slot=>{const i=DECOR.find(i=>i.id===room[slot]);return '<div class="room-piece">'+(i?lifeArt('decor',i):'<div class="empty-piece">＋</div>')+'<small>'+(i?i.name:slot)+'</small>'+(i?'<button class="room-remove" data-action="life-remove" data-id="'+slot+'" aria-label="Put '+i.name+' back in collection">Put away</button>':'')+'</div>';}).join('')+'</div></div>';}
function homeExterior(h,car){return '<div class="home-exterior" role="img" aria-label="'+esc(h.name+(car?' with your '+car.name+' parked outside':', your current residence'))+'"><div class="home-moon"></div><div class="home-ground"></div><div class="home-drive"></div><img class="residence-building" src="assets/life/home-'+h.id+'.webp?v=4" alt="" decoding="async">'+(car?'<img class="parked-vehicle '+(car.id==='bike'?'parked-bike':'')+'" src="assets/life/park-'+car.id+'.webp?v=4" alt="" decoding="async">':'')+'<div class="exterior-caption"><span>'+esc(h.name)+'</span><small>'+(car?esc(car.name)+' · parked at home':'Your own little corner of the city')+'</small></div></div>';}
function renderLife(){const l=syncLife(S),h=activeHome(),car=CARS.find(c=>c.id===l.car),ownedHomes=HOMES.filter(h=>l.homes[h.id]);let body='';
 if(l.view==='home')body='<div class="life-overview"><div>'+homeExterior(h,car)+'<div class="life-home-caption"><div><span class="eyebrow">CURRENT RESIDENCE</span><h2>'+h.name+'</h2><p>'+h.desc+'</p></div>'+button('Decorate this home','life-view','decorate',null,false,'primary')+'</div></div><aside class="panel"><div class="eyebrow">YOUR COLLECTION</div><h3>A little more you.</h3><div class="line"><span>Homes owned</span><strong>'+ownedHomes.length+' / '+HOMES.length+'</strong></div><div class="line"><span>Decor collected</span><strong>'+Object.keys(l.decor).length+' / '+DECOR.length+'</strong></div><div class="line"><span>Vehicles</span><strong>'+Object.keys(l.cars).length+' / '+CARS.length+'</strong></div><div class="divider"></div><h3>Daily driver</h3>'+(car?lifeArt('car',car)+'<p>'+car.name+'</p>':'<p>Your next adventure starts on foot.</p>')+button('Visit garage','life-view','garage',null,false,'full ghost')+'<div class="divider"></div><p>Your active home and placed decor add comfort. Only your selected vehicle adds a driving bonus.</p></aside></div>';
 if(l.view==='properties')body='<div class="life-section-intro"><h2>Find your next address.</h2><p>Buy outright, keep your previous homes, and move between them whenever you like. Personal homes do not earn rent.</p></div><div class="life-catalog">'+HOMES.map(x=>'<article class="card '+(l.homes[x.id]?'owned':'')+'">'+lifeArt('home',x)+'<span class="eyebrow">'+x.rooms+(x.rooms===1?' ROOM · ':' ROOMS · ')+x.comfort+' BASE COMFORT</span><h3>'+x.name+'</h3><p>'+x.desc+'</p><div class="actions">'+(l.homes[x.id]?button(l.home===x.id?'Living here ✓':'Move in','life-home',x.id,null,l.home===x.id):button('Buy · '+money(x.cost),'life-buy-home',x.id,x.cost))+'</div></article>').join('')+'</div>';
 if(l.view==='decorate'){const room=l.layouts[h.id]?.[l.room]||{};body='<div class="life-section-intro"><h2>Make '+h.name.toLowerCase()+' yours.</h2><p>One piece per category in each room. Swap freely; replaced pieces stay in your collection. Each home keeps its own arrangement.</p></div><div class="choice-row">'+ROOMS.slice(0,h.rooms).map((r,i)=>'<button class="btn ghost" data-action="life-room" data-id="'+i+'" aria-pressed="'+(l.room===i)+'">'+r+'</button>').join('')+'</div>'+roomPreview()+'<div class="choice-row">'+['all','seating','storage','lighting','accent'].map(f=>'<button class="btn ghost" data-action="life-filter" data-id="'+f+'" aria-pressed="'+(l.filter===f)+'">'+(f==='all'?'All furnishings':f[0].toUpperCase()+f.slice(1))+'</button>').join('')+'</div><div class="life-catalog">'+DECOR.filter(i=>l.filter==='all'||i.slot===l.filter).map(i=>'<article class="card '+(l.decor[i.id]?'owned':'')+'">'+lifeArt('decor',i)+'<span class="eyebrow">'+i.slot+' · +'+i.comfort+' COMFORT</span><h3>'+i.name+'</h3><div class="actions">'+(l.decor[i.id]?button(room[i.slot]===i.id?'Placed here ✓':'Place in room','life-place',i.id,null,room[i.slot]===i.id):button('Collect · '+money(i.cost),'life-buy-decor',i.id,i.cost))+'</div></article>').join('')+'</div><p class="life-footnote">Furnishing comfort is capped at +30 across your active home. Other homes keep their furnishings for your next move.</p>';}
 if(l.view==='garage')body='<div class="life-section-intro"><h2>Keys to the next chapter.</h2><p>Collect your favorites and choose a daily driver. The strongest bonus applies alongside your existing transport upgrades; car bonuses do not stack.</p></div><div class="life-catalog">'+CARS.map(c=>'<article class="card '+(l.cars[c.id]?'owned':'')+'">'+lifeArt('car',c)+'<span class="eyebrow">+'+Math.round(c.bonus*100)+'% TRANSPORT PAY BONUS</span><h3>'+c.name+'</h3><p>'+c.desc+'</p><div class="actions">'+(l.cars[c.id]?button(l.car===c.id?'Daily driver ✓':'Drive this','life-car',c.id,null,l.car===c.id):button('Buy · '+money(c.cost),'life-buy-car',c.id,c.cost))+'</div></article>').join('')+'</div>';
 if(l.view==='activities')body='<div class="section-title"><h2>Time for yourself</h2></div><div class="life-catalog">'+HOBBIES.map(h=>{const level=S.hobbies[h.id]||0;return '<article class="card">'+thumb(h.scene)+'<h3>'+h.name+'</h3><p>Level '+level+'/10 · +0.5 comfort and 15 '+PATH(h.skill).skill+' XP per level.</p><p>'+(S.leisure?.id===h.id?'In progress: '+live('leisure',duration(S.leisure.remaining)):duration(45+level*20)+' per session')+'</p>'+button(level>=10?'Mastered':'Practice · '+money(100*2**level),'hobby',h.id,100*2**level,level>=10||!!S.leisure)+'</article>';}).join('')+'</div><div class="section-title"><h2>Everyday upgrades & experiences</h2></div><div class="life-catalog">'+ITEMS.filter(i=>!['bike','car','apartment','house'].includes(i.id)).map(i=>'<article class="card"><h3>'+i.name+'</h3><p>'+i.desc+'</p>'+button(S.items[i.id]?'Owned ✓':money(i.cost),'item',i.id,i.cost,!!S.items[i.id])+'</article>').join('')+'</div>';
 if(l.view==='garage'&&car)body='<div class="garage-feature"><div><span class="eyebrow">YOUR DAILY DRIVER</span><h2>'+car.name+'</h2><p>'+car.desc+'</p><strong>+'+Math.round(car.bonus*100)+'% transport pay</strong></div>'+lifeArt('car',car)+'</div>'+body;return '<div class="life-page">'+heading('YOUR LIFE / MAKE IT YOURS','Build a life beyond the paycheck.','Your address. Your style. Your own way around.')+'<div class="life-stats"><span><small>AT HOME</small><strong>'+h.name+'</strong></span><span><small>COMFORT</small><strong>'+comfort().toFixed(1)+'</strong></span><span><small>COMFORT PAY BONUS</small><strong>+'+(comfort()*1.5).toFixed(1)+'%</strong></span></div><nav class="life-tabs" aria-label="Life sections">'+[['home','At home'],['properties','Properties'],['decorate','Decorate'],['garage','Garage'],['activities','Hobbies & extras']].map(([id,title])=>'<button data-action="life-view" data-id="'+id+'" aria-pressed="'+(l.view===id)+'">'+title+'</button>').join('')+'</nav>'+body+'</div>';
}

function defaults(){return {v:2,life:freshLife(),cash:0,earned:0,clicks:0,path:'culinary',careers:Object.fromEntries(PATHS.map(p=>[p.id,{rank:0,xp:0,courses:0,spec:'',contracts:0}])),business:{},properties:{},items:{},hobbies:{},holdings:{},market:Object.fromEntries(FUNDS.map(f=>[f.id,{price:f.price,hist:[f.price],basis:0}])),marketClock:0,marketDays:0,training:null,leisure:null,contract:null,claims:{},log:[],legacy:0,generation:1,lifetime:0,archiveValue:0,archiveIncome:0,auto:true,last:Date.now(),tab:'work',careerView:'culinary',businessFilter:'all',casino:{budget:0,spent:0,plays:0,won:0,lost:0,game:'roulette',hand:null,result:'Choose a table and set a session budget.',symbols:['★','◆','♣'],roulette:null},settings:{motion:true},migration:false};}
let S=defaults(), paused=false, lastFrame=Date.now(), saveClock=0, renderNeeded=false, modalFocus=null, workHold=null, workHoldStart=0, lastWorkAt=0;
function normalize(raw){
 if(!raw||typeof raw!=='object'||raw.v!==2)throw Error('This is not a Clock Out version 2 save.');
 const d=defaults();
 for(const k of ['cash','earned','clicks','legacy','lifetime','archiveValue','archiveIncome','marketDays'])d[k]=num(raw[k]);
 d.generation=Math.max(1,Math.floor(num(raw.generation,1e6)));d.last=num(raw.last,Date.now())||Date.now();
 d.path=PATHS.some(p=>p.id===raw.path)?raw.path:'culinary';d.careerView=PATHS.some(p=>p.id===raw.careerView)?raw.careerView:d.path;
 d.tab=NAV.some(n=>n.id===raw.tab)?raw.tab:'work';d.auto=raw.auto!==false;d.migration=!!raw.migration;d.settings.motion=raw.settings?.motion!==false;
 PATHS.forEach(p=>{const c=raw.careers?.[p.id]||{};d.careers[p.id]={rank:Math.floor(num(c.rank,4)),xp:num(c.xp,1e9),courses:Math.floor(num(c.courses,4)),contracts:Math.floor(num(c.contracts,1e6)),spec:p.specs.some(x=>x[0]===c.spec)?c.spec:''};});
 BUSINESSES.forEach(b=>{const q=raw.business?.[b.id];if(q&&q.level>0)d.business[b.id]={level:Math.max(1,Math.floor(num(q.level,25))),staff:Math.floor(num(q.staff,10)),equipment:Math.floor(num(q.equipment,10)),strategy:['steady','premium','volume'].includes(q.strategy)?q.strategy:'steady'};});
 PROPERTIES.forEach(p=>{if(raw.properties?.[p.id])d.properties[p.id]={renovation:Math.floor(num(raw.properties[p.id].renovation,5))};});
 ITEMS.forEach(i=>{if(raw.items?.[i.id]===true)d.items[i.id]=true;});HOBBIES.forEach(h=>{d.hobbies[h.id]=Math.floor(num(raw.hobbies?.[h.id],10));});
 FUNDS.forEach(f=>{const m=raw.market?.[f.id]||{};d.market[f.id]={price:f.id==='savings'?1:clamp(num(m.price)||f.price,.1,1e8),basis:num(m.basis),hist:Array.isArray(m.hist)?m.hist.slice(-40).map(x=>clamp(num(x),.1,1e8)):[f.price]};d.holdings[f.id]=num(raw.holdings?.[f.id]);});
 d.marketClock=num(raw.marketClock,59.99);
 if(raw.training&&PATHS.some(p=>p.id===raw.training.path)&&raw.training.tier===d.careers[raw.training.path].courses&&raw.training.tier<4)d.training={path:raw.training.path,tier:raw.training.tier,remaining:num(raw.training.remaining,3600)};
 if(raw.leisure&&HOBBIES.some(h=>h.id===raw.leisure.id))d.leisure={id:raw.leisure.id,remaining:num(raw.leisure.remaining,3600)};
 if(raw.contract&&PATHS.some(p=>p.id===raw.contract.path))d.contract={path:raw.contract.path,progress:num(raw.contract.progress,500),target:clamp(num(raw.contract.target),1,500),reward:num(raw.contract.reward,1e9)};
 GOALS.forEach(g=>{if(raw.claims?.[g.id]===true)d.claims[g.id]=true;});
 d.log=Array.isArray(raw.log)?raw.log.slice(0,30).filter(x=>typeof x==='string').map(x=>x.slice(0,200)):[];
 const c=raw.casino||{};for(const k of ['budget','spent','plays','won','lost'])d.casino[k]=num(c[k]);d.casino.spent=Math.min(d.casino.spent,d.casino.budget);d.casino.game=['roulette','slots','coin','blackjack'].includes(c.game)?c.game:'roulette';
 // Hands are persisted so a reload cannot erase a losing hand or refund a stake.
 if(c.hand&&c.hand.live===true){const h=c.hand,cardOk=v=>Number.isInteger(v)&&v>=0&&v<52;if(Array.isArray(h.deck)&&h.deck.length<=104&&h.deck.every(cardOk)&&Array.isArray(h.p)&&h.p.length>=2&&h.p.length<15&&h.p.every(cardOk)&&Array.isArray(h.d)&&h.d.length>=2&&h.d.length<15&&h.d.every(cardOk)&&num(h.bet)>0)d.casino.hand={deck:h.deck,p:h.p,d:h.d,bet:num(h.bet),live:true};}
 if(d.casino.hand?.live)d.casino.result='Your saved hand is waiting. Hit, stand, or double.';
 normalizeLife(raw.life,d);return d;
}
const NAV=[{id:'work',name:'Work',icon:'▣',group:'YOUR EVERYDAY'},{id:'careers',name:'Careers',icon:'↗'},{id:'school',name:'Education',icon:'▤'},{id:'life',name:'Your life',icon:'⌂'},{id:'city',name:'The city',icon:'▦',group:'A BIGGER WORLD'},{id:'business',name:'Businesses',icon:'▥'},{id:'invest',name:'Investments',icon:'◴'},{id:'casino',name:'The Velvet Room',icon:'♠'},{id:'journal',name:'Milestones',icon:'☆',group:'YOUR STORY'},{id:'settings',name:'Save & settings',icon:'⚙'}];
function migrate(old){
 const d=defaults();d.migration=true;d.cash=num(old.cash);d.earned=num(old.earned);d.clicks=num(old.clicks);d.legacy=num(old.legacy,1000000);d.generation=Math.max(1,num(old.gens));d.lifetime=num(old.lifetime?.earned)||d.earned;d.last=num(old.last,Date.now())||Date.now();
 const jobs={fry:['culinary',0],cashier:['culinary',0],barista:['culinary',1],delivery:['trades',0],temp:['finance',0],sales:['finance',1],jrdev:['tech',1],accountant:['finance',2],engineer:['tech',2],lawyer:['finance',3],doctor:['medicine',3],director:['finance',3],vp:['finance',4],ceo:['finance',4],hedge:['finance',4],mogul:['finance',4]};
 for(const [id,count] of Object.entries(old.jobClicks||{})){const [path,rank]=jobs[id]||['culinary',0];const c=d.careers[path];c.rank=Math.max(c.rank,rank);c.xp+=num(count,1e9);c.courses=Math.max(c.courses,rank);}
 const [path,rank]=jobs[old.job]||['culinary',0];d.path=path;d.careerView=path;d.careers[path].rank=Math.max(d.careers[path].rank,rank);d.careers[path].courses=Math.max(d.careers[path].courses,rank);d.careers[path].xp=Math.max(d.careers[path].xp,XP_REQ[rank]);
 ITEMS.forEach(i=>{if(old.assets?.[i.id])d.items[i.id]=true;});
 // Unsupported holdings become a clearly labeled, income-bearing legacy trust.
 const legacyH=[['lemonade',60,.6],['dogs',350,3.5],['delivery',1800,16],['etsy',9000,70],['youtube',45000,320],['dropship',220000,1400],['podcast',1.2e6,6500],['appstudio',7e6,35000]];
 const legacyB=[['truck',30000,180],['laundro',150000,800],['carwash',600000,3000],['restaurant',2.5e6,11000],['franchise',12e6,48000],['startup',60e6,220000],['bank',400e6,1.3e6],['space',3e9,9e6]];
 for(const [list,owned] of [[legacyH,old.hustles],[legacyB,old.biz]])for(const [id,cost,rate] of list){const n=Math.floor(num(owned?.[id],100000));d.archiveValue+=Math.min(1e30,cost*(1.15**Math.min(n,490)-1)/.15*.5);d.archiveIncome+=num(rate*n*2**[10,25,50,100,200,500,1000].filter(t=>n>=t).length);}
 const oldIdleEducation={bachelors:.1,mba:.25,phd:.5},oldIdleAssets={phone:.05,apartment:.1,house:.2,penthouse:.25,yacht:.3,jet:.5,island:1};
 const idleBoost=1+Object.entries(oldIdleEducation).reduce((n,[id,v])=>n+(old.edu?.[id]?v:0),0)+Object.entries(oldIdleAssets).reduce((n,[id,v])=>n+(old.assets?.[id]?v:0),0);d.archiveIncome*=idleBoost*(1+.1*d.legacy);
 const oldQualifications={ged:[['finance',1]],college:[['finance',2],['creative',1]],bootcamp:[['tech',2]],bachelors:[['tech',3],['finance',3]],mba:[['finance',4]],law:[['finance',4]],med:[['medicine',4]],phd:[['tech',4]]};
 for(const [id,qualifications] of Object.entries(oldQualifications))if(old.edu?.[id])for(const [p,t] of qualifications)d.careers[p].courses=Math.max(d.careers[p].courses,t);
 const oldItemCosts={bike:250,phone:900,car:6000,apartment:60000,assistant:25000,house:750000,team:2e6};for(const i of ITEMS)if(d.items[i.id]&&oldItemCosts[i.id])d.archiveValue+=Math.max(0,oldItemCosts[i.id]-i.cost);
 for(const v of Object.values(old.invest||{}))d.holdings.savings=(d.holdings.savings||0)+num(v?.bal);d.market.savings.basis=d.holdings.savings||0;
 const extraAssets={sportscar:150000,penthouse:5e6,yacht:30e6,jet:150e6,clones:2e8,island:2e9};for(const [id,cost]of Object.entries(extraAssets))if(old.assets?.[id])d.archiveValue+=cost;
 const oldPay={fry:7.25,cashier:9.5,barista:12,delivery:16,temp:20,sales:32,jrdev:48,accountant:65,engineer:120,lawyer:260,doctor:420,director:700,vp:1500,ceo:4000,hedge:12000,mogul:60000};
 const eduClick={ged:.1,college:.15,bootcamp:.2,bachelors:.3,mba:.5,law:.5,med:.6,phd:.3},assetClick={bike:.05,car:.1,sportscar:.2,penthouse:.25,yacht:.3,jet:.5,island:1};
 const oldClickBoost=1+Object.entries(eduClick).reduce((n,[id,v])=>n+(old.edu?.[id]?v:0),0)+Object.entries(assetClick).reduce((n,[id,v])=>n+(old.assets?.[id]?v:0),0);
 const oldAuto=(old.assets?.assistant?1:0)+(old.assets?.team?5:0)+(old.assets?.clones?30:0),oldLevel=Math.min(10,Math.floor(Math.sqrt(num(old.jobClicks?.[old.job])/20)));
 d.archiveIncome+=Math.max(0,oldAuto*(oldPay[old.job]||7.25)*(1+.15*oldLevel)*oldClickBoost*(1+.1*d.legacy)-automatic(d)*clickPay(d));
 for(const k of ['won','lost','plays'])d.casino[k]=num(old.casino?.[k]);
 d.log=['Your Grind save was imported. Original save retained. Existing businesses are held in the legacy trust; investment balances moved to the cash reserve.'];return normalize(d);
}
function load(){try{const raw=localStorage.getItem(KEY);if(raw)S=normalize(JSON.parse(raw));else{const old=localStorage.getItem('grind.v1');if(old)S=migrate(JSON.parse(old));}}catch(e){paused=true;loadError='Your saved data could not be read. Nothing has been overwritten. Use Save & settings to import a backup or download the unreadable save.';}}
let loadError='';
function save(){if(paused)return false;S.last=Date.now();try{localStorage.setItem(KEY,JSON.stringify(S));try{localStorage.setItem('clockout.leaderboard.snapshot.v1',JSON.stringify({version:1,netWorth:netWorth(),generation:S.generation,savedAt:S.last}));}catch{};if(typeof document!=='undefined')$('#save-status').textContent='● SAVED LOCALLY';return true;}catch(e){if(typeof document!=='undefined')$('#save-status').textContent='SAVE FAILED — EXPORT BACKUP';return false;}}
const career=(s=S)=>s.careers[s.path];
function comfort(s=S){return lifeComfort(s)+ITEMS.reduce((n,i)=>n+(i.kind==='comfort'&&s.items[i.id]?i.bonus:0),0)+Object.values(s.hobbies).reduce((a,b)=>a+b,0)*.5;}
function clickPay(s=S){const c=career(s),p=PATH(s.path);return p.pay[c.rank]*(1+vehicleBoost(s)+ITEMS.reduce((n,i)=>n+(i.kind==='work'&&s.items[i.id]?i.bonus:0),0)+comfort(s)*.015)*(1+.1*s.legacy)*(c.spec===p.specs[0][0]?1.25:1)*(1+Math.min(.3,Math.floor(c.xp/100)*.01));}
function automatic(s=S){return s.auto?(s.clicks>=30?.1:0)+ITEMS.reduce((n,i)=>n+(i.kind==='auto'&&s.items[i.id]?i.bonus:0),0):0;}
function businessDetail(b,s=S){const q=s.business[b.id];if(!q)return {gross:0,costs:0,net:0};const c=s.careers[b.path],p=PATH(b.path),strategy=q.strategy==='premium'?1.15:q.strategy==='volume'?1.28:1;const synergy=1+c.rank*.06+(c.spec===p.specs[1][0]?.25:0);const gross=b.rate*q.level*(1+q.equipment*.2)*(1+q.staff*.12)*strategy*synergy*(1+s.legacy*.1)*(s.items.phone?1.05:1);const overhead=q.strategy==='volume'?.28:q.strategy==='premium'?.21:.12;return {gross,costs:gross*overhead,net:gross*(1-overhead)};}
function propertyRate(s=S){return PROPERTIES.reduce((a,p)=>a+(s.properties[p.id]?p.rate*(1+s.properties[p.id].renovation*.25)*.85:0),0);}
function incomeRate(s=S){return BUSINESSES.reduce((a,b)=>a+businessDetail(b,s).net,0)+propertyRate(s)+automatic(s)*clickPay(s)+s.archiveIncome;}
function portfolioValue(s=S){return FUNDS.reduce((n,f)=>n+(s.holdings[f.id]||0)*s.market[f.id].price,0);}
function netWorth(s=S){return lifeWorth(s)+s.cash+portfolioValue(s)+s.archiveValue+BUSINESSES.reduce((n,b)=>n+(s.business[b.id]?b.cost*s.business[b.id].level:0),0)+ITEMS.reduce((n,i)=>n+(s.items[i.id]?i.cost:0),0)+PROPERTIES.reduce((n,p)=>n+(s.properties[p.id]?p.cost:0),0);}
function earn(n){if(!Number.isFinite(n)||n<0)return;S.cash=num(S.cash+n);S.earned=num(S.earned+n);S.lifetime=num(S.lifetime+n);}
function spend(n){if(paused||!Number.isFinite(n)||n<=0||S.cash+1e-7<n)return false;S.cash=Math.max(0,S.cash-n);return true;}
function note(msg){S.log.unshift(msg);S.log=S.log.slice(0,30);if(typeof document!=='undefined')toast(msg);}
function nextGoal(){return GOALS.find(g=>!S.claims[g.id]);}
function chapter(){return career().rank>=4?'06 / CLOCK OUT':S.items.house?'05 / ROOM TO GROW':Object.values(S.business).some(b=>b.level>=3)?'04 / BUILD SOMETHING':S.items.apartment?'03 / YOUR OWN KEYS':career().rank>=1?'02 / BREATHING ROOM':'01 / FIRST SHIFT';}
function startCourse(path){const c=S.careers[path];if(!PATHS.some(p=>p.id===path)||S.training||c.courses>=4||!spend(COURSE_COST[c.courses]))return false;const tier=c.courses;S.training={path,tier,remaining:COURSE_TIME[tier]*(S.items.desk?0.85:1)};note(`Started ${PATH(path).courses[tier]}.`);return true;}
function promote(path){const c=S.careers[path];if(!PATHS.some(p=>p.id===path)||c.rank>=4||c.xp<XP_REQ[c.rank+1]||c.courses<c.rank+1||paused)return false;c.rank++;note(`Promoted to ${PATH(path).roles[c.rank]}!`);return true;}
function switchCareer(path){if(!PATHS.some(p=>p.id===path)||paused||(S.clicks<10&&path!=='culinary'))return false;S.path=path;S.careerView=path;note(`Now working in ${PATH(path).name}. All career progress is kept.`);return true;}
function specialize(path,id){const c=S.careers[path];if(!PATHS.some(p=>p.id===path)||c.rank<2||c.spec||paused||!PATH(path).specs.some(x=>x[0]===id))return false;c.spec=id;note(`${PATH(path).name}: ${PATH(path).specs.find(x=>x[0]===id)[1]} specialization selected.`);return true;}
function contractStart(){if(S.contract||career().rank<1||paused)return false;const n=career().contracts;S.contract={path:S.path,progress:0,target:Math.min(160,25+n*5),reward:PATH(S.path).pay[career().rank]*(40+Math.min(n,30)*4)};return true;}
function workAction(){if(paused)return false;const pay=clickPay();earn(pay);S.clicks++;career().xp+=1+comfort()*.02;if(S.contract&&S.contract.path===S.path){S.contract.progress++;if(S.contract.progress>=S.contract.target){const reward=S.contract.reward;career().contracts++;career().xp+=20;S.contract=null;earn(reward);note(`Contract delivered. ${money(reward)} earned and +20 career XP.`);renderNeeded=true;}}if(S.clicks===10||S.clicks===30)renderNeeded=true;return pay;}
function buyItem(id){const i=ITEMS.find(x=>x.id===id);if(!i||S.items[id]||!spend(i.cost))return false;S.items[id]=true;note(`${i.name} is now part of your life.`);return true;}
function businessCost(b,q){return Math.ceil(b.cost*1.45**(q?.level||0));}
function businessBuy(id){const b=BUSINESSES.find(x=>x.id===id),q=S.business[id];if(!b||(q?.level||0)>=25||!spend(businessCost(b,q)))return false;if(!q)S.business[id]={level:1,staff:0,equipment:0,strategy:'steady'};else q.level++;note(`${b.name}: level ${S.business[id].level}.`);return true;}
function improveBusiness(id,kind){const b=BUSINESSES.find(x=>x.id===id),q=S.business[id];if(!b||!q||!['staff','equipment'].includes(kind)||q[kind]>=10||!spend(Math.ceil(b.cost*.35*1.7**q[kind])))return false;q[kind]++;return true;}
function buyProperty(id){const p=PROPERTIES.find(x=>x.id===id);if(!p||S.properties[id]||!spend(p.cost))return false;S.properties[id]={renovation:0};note(`You own ${p.name.toLowerCase()}.`);return true;}
function renovate(id){const p=PROPERTIES.find(x=>x.id===id),q=S.properties[id];if(!p||!q||q.renovation>=5||!spend(p.cost*.25*1.7**q.renovation))return false;q.renovation++;return true;}
function startHobby(id){const h=HOBBIES.find(x=>x.id===id),l=S.hobbies[id]||0;if(!h||S.leisure||l>=10||!spend(100*2**l))return false;S.leisure={id,remaining:45+l*20};return true;}
function trade(id,amount,sell=false){const f=FUNDS.find(x=>x.id===id);if(!f||!Number.isFinite(amount)||amount<=0||paused)return false;const m=S.market[id],owned=S.holdings[id]||0;if(sell){const units=Math.min(owned,amount/m.price);if(!units)return false;S.holdings[id]=Math.max(0,owned-units);m.basis=owned>0?m.basis*(S.holdings[id]/owned):0;S.cash=num(S.cash+units*m.price);}else{if(!spend(amount))return false;S.holdings[id]=owned+amount/m.price;m.basis+=amount;}return true;}
function rebalance(amounts){const total=amounts.reduce((a,b)=>a+b,0);if(amounts.length!==FUNDS.length||amounts.some(n=>!Number.isFinite(n)||n<0)||Math.abs(total-100)>.001||paused)return false;const value=portfolioValue();if(value<=0)return false;FUNDS.forEach((f,i)=>{S.holdings[f.id]=value*amounts[i]/100/S.market[f.id].price;S.market[f.id].basis=value*amounts[i]/100;});note('Portfolio rebalanced. Cost basis starts at this allocation.');return true;}
function marketDay(random=Math.random){S.marketDays++;FUNDS.forEach(f=>{const m=S.market[f.id];if(f.id==='savings'){earn((S.holdings[f.id]||0)*f.drift);}else{const shock=(random()-.5)*2;const cycle=Math.sin(S.marketDays/14)*f.vol*.12;m.price=clamp(m.price*(1+f.drift+shock*f.vol+cycle),.1,1e8);}m.hist.push(m.price);if(m.hist.length>40)m.hist.shift();});if(typeof document!=='undefined'&&S.tab==='invest'){document.querySelectorAll('.market-chart[data-fund]').forEach(el=>{const fund=FUNDS.find(f=>f.id===el.dataset.fund);if(fund)el.outerHTML=spark(fund);});}}
function advance(seconds,away=false,random=Math.random){
 if(paused||!Number.isFinite(seconds)||seconds<=0)return 0;seconds=Math.min(seconds,MAX_OFFLINE);const gained=incomeRate()*seconds;earn(gained);const beforeXP=career().xp;career().xp+=automatic()*seconds*.3;if(career().rank<4&&beforeXP<XP_REQ[career().rank+1]&&career().xp>=XP_REQ[career().rank+1])renderNeeded=true;
 for(const key of ['training','leisure']){const task=S[key];if(!task)continue;task.remaining=Math.max(0,task.remaining-seconds);if(task.remaining===0){if(key==='training'){S.careers[task.path].courses=Math.max(S.careers[task.path].courses,task.tier+1);S.careers[task.path].xp+=25;note(`Completed ${PATH(task.path).courses[task.tier]}.`);}else{const h=HOBBIES.find(x=>x.id===task.id);S.hobbies[task.id]=Math.min(10,(S.hobbies[task.id]||0)+1);S.careers[h.skill].xp+=15;note(`${h.name} reached level ${S.hobbies[task.id]}.`);}S[key]=null;renderNeeded=true;}}
 // Risk assets stay flat while away; the stable cash reserve earns simple interest.
 if(away){earn((S.holdings.savings||0)*FUNDS[0].drift*seconds/60);}else{S.marketClock+=seconds;while(S.marketClock>=60){S.marketClock-=60;marketDay(random);}}
 return gained;
}
function claim(id){const g=GOALS.find(x=>x.id===id);if(!g||S.claims[id]||!g.test(S)||paused)return false;S.claims[id]=true;earn(g.reward);note(`Milestone: ${g.name}. +${money(g.reward)}.`);return true;}

// Casino outcomes resolve synchronously. No timers can pay out a discarded save.
function sessionStart(amount){if(paused||S.casino.hand?.live||!Number.isFinite(amount)||amount<1||amount>S.cash)return false;S.casino.budget=amount;S.casino.spent=0;S.casino.result=`Session set to ${money(amount)}. Stakes reduce the remaining budget.`;return true;}
function canBet(bet){return !paused&&Number.isFinite(bet)&&bet>=1&&bet<=S.cash&&bet<=S.casino.budget-S.casino.spent;}
function wager(bet){if(!canBet(bet))return false;S.cash-=bet;S.casino.spent+=bet;S.casino.plays++;return true;}
function settle(bet,payout,message){S.cash=num(S.cash+payout);if(payout>=bet)S.casino.won+=payout-bet;else S.casino.lost+=bet-payout;S.casino.result=message+` · ${signed(payout-bet)} net`;}
const REDS=new Set([1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36]);
function roulette(bet,pick,random=Math.random){if(S.casino.hand?.live||!['red','black','odd','even','zero'].includes(pick)||!wager(bet))return false;const n=Math.floor(random()*37);S.casino.roulette=n;const win=pick==='zero'?n===0:n!==0&&(pick==='red'?REDS.has(n):pick==='black'?!REDS.has(n):pick==='odd'?n%2===1:n%2===0);settle(bet,win?bet*(pick==='zero'?36:2):0,`Ball lands on ${n}${n===0?'':REDS.has(n)?' red':' black'}`);return true;}
function coin(bet,pick,random=Math.random){if(S.casino.hand?.live||!['heads','tails'].includes(pick)||!wager(bet))return false;const result=random()<.5?'heads':'tails';settle(bet,result===pick?bet*1.9:0,result==='heads'?'Heads':'Tails');return true;}
function slots(bet,random=Math.random){if(S.casino.hand?.live||!wager(bet))return false;const symbols=['★','◆','♣','●','♥'],pay=[20,12,8,5,3],r=[0,0,0].map(()=>Math.floor(random()*5));S.casino.symbols=r.map(i=>symbols[i]);const mult=r.every(n=>n===r[0])?pay[r[0]]:r.filter(n=>n===4).length===2?5:0;settle(bet,bet*mult,mult?`${mult}× total return`:'No matching combination');return true;}
function deck(random=Math.random){const d=Array.from({length:104},(_,i)=>i%52);for(let i=d.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[d[i],d[j]]=[d[j],d[i]];}return d;}
function handValue(cards){let n=0,aces=0;cards.forEach(c=>{const r=c%13;if(r===0){n+=11;aces++;}else n+=Math.min(10,r+1);});while(n>21&&aces){n-=10;aces--;}return n;}
function blackjackDeal(bet,random=Math.random){if(S.casino.hand?.live||!wager(bet))return false;const d=deck(random);S.casino.hand={deck:d,p:[d.pop(),d.pop()],d:[d.pop(),d.pop()],bet,live:true};S.casino.result='Hit, stand, or double.';if(handValue(S.casino.hand.p)===21||handValue(S.casino.hand.d)===21)blackjackEnd();return true;}
function blackjackEnd(){const h=S.casino.hand;if(!h?.live||paused)return false;const p=handValue(h.p),pn=p===21&&h.p.length===2,dn=handValue(h.d)===21&&h.d.length===2;if(p<=21&&!pn&&!dn)while(handValue(h.d)<17)h.d.push(h.deck.pop());const d=handValue(h.d);let payout=0,msg='Dealer wins';if(p>21)msg='Bust';else if(pn&&dn){payout=h.bet;msg='Two naturals. Push';}else if(dn)msg='Dealer blackjack';else if(pn){payout=h.bet*2.5;msg='Blackjack!';}else if(d>21||p>d){payout=h.bet*2;msg=d>21?'Dealer busts':'You win';}else if(p===d){payout=h.bet;msg='Push';}h.live=false;settle(h.bet,payout,msg);return true;}
function blackjackHit(){const h=S.casino.hand;if(!h?.live||paused)return false;h.p.push(h.deck.pop());if(handValue(h.p)>=21)blackjackEnd();return true;}
function blackjackDouble(){const h=S.casino.hand;if(!h?.live||h.p.length!==2||!canBet(h.bet))return false;S.cash-=h.bet;S.casino.spent+=h.bet;h.bet*=2;h.p.push(h.deck.pop());blackjackEnd();return true;}

// UI. Tick updates only numeric bindings and affordability, preserving form focus.
const SCENES=['diner','starter-room','city','studio','workshop','clinic','office','loft','casino'];
const prefersStill=()=>!S.settings.motion||(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches);
const sceneURL=(i,animated=false,thumbnail=false)=>'assets/scenes/'+SCENES[i]+(thumbnail?'.thumb.webp':animated?'.gif?v=2':'.webp');
function sceneImage(i,{animated=false,alt='',cls='scene-image',lazy=false}={}){return `<img class="${cls}" src="${sceneURL(i,animated&&!prefersStill(),cls==='scene-thumbnail')}" ${animated?`data-animated-scene="${i}"`:''} width="1920" height="1080" alt="${esc(alt)}" decoding="async" ${lazy?'loading="lazy"':''}>`;}
function syncSceneMotion(){document.querySelectorAll('[data-animated-scene]').forEach(img=>{const i=Number(img.dataset.animatedScene),url=sceneURL(i,!prefersStill());if(img.getAttribute('src')!==url)img.src=url;});}
const thumb=(i,cls='thumb')=>`<div class="${cls}" aria-hidden="true">${sceneImage(i,{lazy:true,cls:'scene-thumbnail'})}</div>`;
function sceneBanner(i,alt){return `<div class="scene-banner">${sceneImage(i,{animated:true,alt})}</div>`;}
function button(label,action,id='',cost=null,disabled=false,cls=''){return `<button type="button" class="btn ${cls}" data-action="${action}" data-id="${id}"${cost!==null?` data-cost="${cost}"`:''}${disabled?' data-locked="true" disabled':''}>${label}</button>`;}
const live=(key,text,cls='')=>`<span class="${cls}" data-live="${key}">${text}</span>`;
function heading(kicker,title,desc){return `<header class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="page-desc">${desc}</p></div><span class="chapter">${chapter()}</span></header>`;}
function scene(i,title,caption,props=''){return `<section class="scene-card"><div class="scene-label"><span>${title}</span><span>✦ ${i===8?'AFTER HOURS':'YOUR LITTLE CORNER OF THE WORLD'}</span></div><div class="scene-art" id="scene">${sceneImage(i,{animated:true,alt:caption})}<span class="scene-caption">${caption}</span>${props?`<div class="scene-props">${props}</div>`:''}</div></section>`;}
function goalPanel(){const g=nextGoal();return `<section class="panel"><div class="eyebrow">THE NEXT LITTLE WIN</div><h3>${g?g.name:'You made a life of your own.'}</h3><p>${g?g.desc:'Explore another career, complete your collections, or begin a new chapter.'}</p>${g?`<div class="line"><span class="muted">Milestone reward</span><strong class="gold">${money(g.reward)}</strong></div><button class="btn full" data-action="claim" data-id="${g.id}" data-goal="${g.id}">Claim reward</button>`:button('Explore your milestones','navigate','journal',null,false,'full')}</section>`;}
function skillsPanel(){return `<section class="panel"><div class="eyebrow">WHAT YOU'RE BUILDING</div>${PATHS.map(p=>{const c=S.careers[p.id],n=c.rank<4?XP_REQ[c.rank+1]:XP_REQ[4]*2;return `<div class="skill-row"><div class="line"><span>${p.skill}</span>${live('xp-'+p.id,Math.floor(c.xp)+' XP','mono')}</div><div class="track"><i data-progress="skill-${p.id}" style="width:${Math.min(100,c.xp/n*100)}%"></i></div></div>`;}).join('')}</section>`;}
function incomePanel(){return `<section class="panel"><div class="eyebrow">MONEY THAT KEEPS MOVING</div><div class="line"><span>Work routine</span><strong>${live('auto-income',money(automatic()*clickPay())+'/s')}</strong></div><div class="line"><span>Businesses, net</span><strong>${live('business-income',money(BUSINESSES.reduce((n,b)=>n+businessDetail(b).net,0))+'/s')}</strong></div><div class="line"><span>Property, net</span><strong>${money(propertyRate())}/s</strong></div>${S.archiveIncome?`<div class="line"><span>Legacy trust</span><strong>${money(S.archiveIncome)}/s</strong></div>`:''}<p>Net figures include operating costs. Market gains are separate. Idle earnings are capped at 8 hours away.</p></section>`;}
function renderWork(){const p=PATH(S.path),c=career(),g=c.rank<4?XP_REQ[c.rank+1]:XP_REQ[4];const props=ITEMS.filter(i=>S.items[i.id]&&i.kind==='work').map(i=>`<span class="prop-badge">${i.name}</span>`).join('');const recommendations=ITEMS.filter(i=>!S.items[i.id]).slice(0,3);
 return heading('WORK / '+p.name.toUpperCase(),'Small shifts. Bigger tomorrows.','A little progress today. A different life tomorrow.')+`<div class="play-layout"><div class="main-column">${scene(p.scene,p.name.toUpperCase()+' · RANK '+(c.rank+1),c.rank===0?'Everyone starts somewhere.':p.roles[c.rank]+' · A new chapter in your career.',props).replace('id="scene"','id="scene" role="button" tabindex="0" data-action="work" aria-label="'+esc(p.action)+' — click or hold to work"').replace('</section>',`<div class="scene-footer"><div><h2>${p.roles[c.rank]}</h2><p>${p.skill} · ${c.spec?esc(p.specs.find(x=>x[0]===c.spec)[1]):'Make this path your own'}</p></div><span class="badge">RANK ${c.rank+1} / 5</span></div><div style="padding:0 18px"><div class="track gold-track"><i data-progress="work" style="width:${Math.min(100,c.xp/g*100)}%"></i></div></div><div class="work-detail"><span>${live('work-xp',Math.floor(c.xp))} XP</span><span>${c.rank<4?g+' XP + qualification for next rank':'MASTER CAREER'}</span></div><div class="work-controls"><button class="btn primary big" id="work-button" data-action="work">${p.action} <span class="mono">+${live('pay',money(clickPay()))}</span></button><button class="btn ghost" data-action="auto" aria-pressed="${S.auto}" ${S.clicks<30?'disabled data-locked="true"':''}>Routine: ${S.clicks<30?'30 actions':S.auto?'on':'off'}</button></div></section>`)}<div class="section-title"><h2>Make your next move</h2><span>YOUR LIFE, YOUR PACE</span></div><div class="grid"><article class="card">${thumb(6)}<div class="eyebrow">SIX PATHS. YOUR CHOICE.</div><h3>Find your calling</h3><p>Qualifications, specializations, and a career that feels like you.</p><div class="actions">${button('Explore careers ↗','navigate','careers')}</div></article><article class="card">${thumb(S.items.apartment?7:1)}<div class="eyebrow">MORE THAN A PAYCHECK</div><h3>Make yourself at home</h3><p>A better room, a favorite hobby, and something to look forward to.</p><div class="actions">${button('Visit your life ↗','navigate','life')}</div></article></div><div class="kicker">${S.clicks<30?'Tip: click or hold the work button. At 30 actions, your automatic routine begins.':'Your routine keeps earning while you explore. Active work also advances contracts.'}</div></div><aside class="right-column">${goalPanel()}<section class="panel"><div class="eyebrow">A LITTLE BETTER EVERY DAY</div><h3>Useful upgrades</h3>${recommendations.map(i=>`<div class="recommendation">${thumb(i.scene,'tiny-art')}<div><strong>${i.name}</strong><p>${i.desc}</p></div>${button(money(i.cost),'item',i.id,i.cost)}</div>`).join('')||'<p>You have every life upgrade.</p>'}</section>${contractPanel()}${incomePanel()}</aside></div>`;
}
function contractPanel(){const q=S.contract,p=q?PATH(q.path):PATH(S.path);return `<section class="panel"><div class="eyebrow">CONTRACT BOARD</div><h3>${p.project}</h3><p>${q?'Complete active work on the '+p.name+' path. Switching paths preserves this contract.':'One focused project. A bigger payout. Available from career rank 2.'}</p>${q?`<div class="line"><span>Actions completed</span><strong>${live('contract',q.progress+' / '+q.target)}</strong></div><div class="line"><span>Completion bonus</span><strong class="gold">${money(q.reward)}</strong></div>`:button('Accept contract','contract','',null,career().rank<1,'full')}</section>`;}
function renderCareers(){const p=PATH(S.careerView),c=S.careers[p.id];return heading('CAREERS / CHOOSE YOUR DIRECTION','There is more than one way up.','Six careers. Independent progress. Switch paths without starting over.')+`<div class="choice-row" aria-label="Career paths">${PATHS.map(x=>`<button class="btn ghost" data-action="career-view" data-id="${x.id}" aria-pressed="${p.id===x.id}">${x.icon} ${x.name}</button>`).join('')}</div><div class="play-layout"><div class="main-column">${scene(p.scene,p.name.toUpperCase(),p.desc)}<section class="panel wide-panel"><div class="line"><div><div class="eyebrow">${p.skill}</div><h2>${p.name}</h2></div>${p.id===S.path?'<span class="badge">CURRENT PATH</span>':button('Work in this career','switch',p.id,null,S.clicks<10)}</div><p>${S.clicks<10?'Complete 10 work actions to explore every career.':`${Math.floor(c.xp)} XP earned · ${c.courses} qualifications · ${c.contracts} contracts delivered`}</p>${p.roles.map((role,r)=>`<div class="career-step ${r===c.rank?'current':''}"><span class="step-number">${r+1}</span><div><h3>${role}</h3><p>Base ${money(p.pay[r])} / action · ${r===0?'Entry role':p.courses[r-1]}</p>${r>c.rank?`<div class="requirements">${XP_REQ[r]} XP · ${r} qualification${r>1?'s':''}</div>`:''}</div>${r===c.rank?'<span class="badge">CURRENT RANK</span>':r<c.rank?'<span class="badge dim">COMPLETED</span>':button(r===c.rank+1?'Get promoted':'Locked','promote',p.id,null,r!==c.rank+1||c.xp<XP_REQ[r]||c.courses<r)}</div>`).join('')}</section></div><aside class="right-column"><section class="panel"><div class="eyebrow">MAKE IT YOURS</div><h3>Career specialization</h3><p>Choose once per career from rank 3. Both paths can reach the top. Your business specialization stays active when you switch careers.</p>${p.specs.map(x=>`<div class="divider"></div><h3>${x[1]}</h3><p>${x[2]}</p>${button(c.spec===x[0]?'Chosen':c.spec?'Other path':'Choose '+x[1],'specialize',p.id+':'+x[0],null,c.rank<2||!!c.spec,'full')}`).join('')}</section>${skillsPanel()}${goalPanel()}</aside></div>`;}
function renderSchool(){return heading('EDUCATION / OPEN A DOOR','Invest in the person you become.','Qualifications unlock ranks. Work builds the experience to earn them.')+`<div class="play-layout"><div>${sceneBanner(6,'A quiet professional study')}${S.training?`<section class="panel"><div class="eyebrow">COURSE IN PROGRESS</div><h3>${PATH(S.training.path).courses[S.training.tier]}</h3><p>Finishes in ${live('training',duration(S.training.remaining))}. Keep working while you learn.</p></section>`:'<div class="kicker">One course at a time. Training continues while away. A study desk cuts new course times by 15%.</div>'}<div class="section-title"><h2>The next qualification</h2><span>FOUR PER CAREER</span></div><div class="grid">${PATHS.map(p=>{const c=S.careers[p.id],t=c.courses;return `<article class="card"><span class="eyebrow">${p.name}</span><h3>${t<4?p.courses[t]:'Fully qualified'}</h3><p>${t<4?`Unlocks ${p.roles[t+1]}. +25 XP when completed.`:'Every qualification in this career is complete.'}</p><div class="line"><span class="muted">${t}/4 completed</span><strong>${t<4?duration(COURSE_TIME[t]*(S.items.desk?.85:1)):'✓'}</strong></div><div class="actions">${button(t<4?'Enroll · '+money(COURSE_COST[t]):'Completed','course',p.id,t<4?COURSE_COST[t]:null,t>=4||!!S.training)}</div></article>`;}).join('')}</div></div><aside class="right-column">${skillsPanel()}${goalPanel()}</aside></div>`;}
